Here's an implementation of the A* algorithm in Python:

```python
import heapq

class Node:
    def __init__(self, state, parent=None, action=None, cost=0, heuristic_cost=0):
        self.state = state
        self.parent = parent
        self.action = action
        self.cost = cost
        self.heuristic_cost = heuristic_cost

    def __lt__(self, other):
        return self.cost + self.heuristic_cost < other.cost + other.heuristic_cost

def a_star_search(graph, start, goal, heuristic):
    open_set = []
    closed_set = set()

    # Initialize the start node
    start_node = Node(state=start, heuristic_cost=heuristic(start))
    heapq.heappush(open_set, start_node)

    while open_set:
        current_node = heapq.heappop(open_set)

        if current_node.state == goal:
            # Reconstruct the path
            path = []
            while current_node:
                path.append(current_node.state)
                current_node = current_node.parent
            return path[::-1]  # Reverse the path

        closed_set.add(current_node.state)

        # Explore the neighbors
        for neighbor, cost in graph[current_node.state].items():
            if neighbor in closed_set:
                continue

            tentative_cost = current_node.cost + cost + heuristic_cost(neighbor, goal)
            if neighbor not in [node.state for node in open_set] or tentative_cost < [node.cost for node in open_set if node.state == neighbor][0]:
                new_node = Node(state=neighbor, parent=current_node, action=None, cost=tentative_cost, heuristic_cost=heuristic(neighbor))
                heapq.heappush(open_set, new_node)

    return None  # Return None if no path is found

